        score -= 40.0;
    }

    // 4. Global balance: Encourage filling bins that are already "less empty" than the mean
    // to keep the distribution of residuals tight.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
