    // Lookahead coupling: If next_item_size is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Dynamic thresholding based on stream progress
    // As we near the end of the stream, we become more aggressive about filling bins (Best-Fit)
    // and less tolerant of opening new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we approach the end of the stream.
        // We only open a new bin if the average residual of current bins is already poor.
