        score += new_bin_penalty;
    } else {
        // Reward bins that bring the current bin's residual closer to the global mean
        // This promotes uniform distribution of space usage across bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // If this is the only bin that fits, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals too small for any likely future item but too large to be efficient.
    // We heavily penalize residuals that are smaller than the smallest likely item (10) but greater than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Aggressive 2-step lookahead: 
    // If the post_residual can perfectly or nearly accommodate the next item, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.8; 
        } else {
            // Penalize if we are forced to open a new bin later because this one is too tight for the next item.
            score += 20.0;
        }
    }

    // 3. Balancing: If this is the last chance to fit the item (fitting_bins_count == 1), 
    // prioritize it over opening a new bin unless the post_residual is extremely wasteful.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 30.0;
    }

    // 4. Mean Residual Coupling: 
    // Prefer bins that stay close to the global mean residual to maintain uniform bin utilization.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // Calculate a dynamic threshold for opening a new bin based on progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Only open a new bin if the average residual of current bins is already poor (high).
        score = mean_residual + (20.0 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize minimizing the post-placement residual (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small (e.g., < 10), 
    // it's often unusable for future items, so we penalize it quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_res).powi(2) * 2.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we penalize the bin because it will force a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Dynamic thresholding: as the stream progresses, prioritize filling bins more aggressively 
    // (lower score) to reduce open_bins_count, preventing the accumulation of fragmented bins.
    let fill_pressure = (open_bins_count as f64 / 10.0) * progress;
    score += fill_pressure * post_res;

    // Special handling for new bin candidates (bin_residual == bin_capacity).
    // We heavily penalize opening a new bin unless the current best-fit options are extremely poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (e.g., fitting_bins_count is low)
        // or if all other bins have high post_residuals.
        score = 45.0 + (progress * 20.0);
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight.
    // Higher post_residual means more wasted space.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If post_residual can fit the next item, reward this bin.
    // This reduces fragmentation by encouraging "perfect" pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if it leaves very little space after the next item.
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // all existing bins are poorly suited (high post_residual).
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin

        // If we have few open bins, opening a new one is less catastrophic.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Mean Residual Balancing:
    // If this bin's post_residual is significantly better (lower) than the current 
    // mean residual, favor it to bring the overall fragmentation down.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 5. Urgency Calibration:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // 6. Last Chance Logic:
    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // We should favor this over opening a new bin by reducing its penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
