    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // 4. Dead Space Avoidance: Penalize residuals that are too small to fit anything useful (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin, modulated by current efficiency.
        score = 45.0 + (mean_residual * 0.5);

        // If we are late in the stream, make opening new bins more expensive.
        score += progress * 20.0;
    }

    // 6. Last Chance logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
